  item.json._assignedToMe = true;
}
return $input.all();

for (const item of $input.all()) {
  item.json._reportedByMe = true;
}
return $input.all();

const seenTested = new Set();
const seenBugs = new Set();
const tested = [];
const bugs = [];
const myAccountId = '712020:73241cb0-4434-4afb-a9c9-1a320a644c30';
const reportDate = $('Calculate Report Date').first().json.reportDate;

function iActedOnDate(item) {
  // Check comments on report date
  const comments = item.json.fields?.comment?.comments || [];
  const commented = comments.some(c =>
    c.author?.accountId === myAccountId &&
    c.created?.slice(0, 10) === reportDate
  );
  if (commented) return true;

  // Check status changes on report date
  const histories = item.json.changelog?.histories || [];
  const changedStatus = histories.some(h =>
    h.author?.accountId === myAccountId &&
    h.created?.slice(0, 10) === reportDate &&
    h.items?.some(i => i.field === 'status')
  );
  return changedStatus;
}

function iReportedIt(item) {
  return item.json.fields?.reporter?.accountId === myAccountId;
}

function isAssignedToMe(item) {
  return item.json.fields?.assignee?.accountId === myAccountId;
}

const canceledStatuses = ['cancel', 'canceled', 'cancelled'];
const excludedStatuses = ['ready for qa', ...canceledStatuses];

for (const item of $input.all()) {
  const key = item.json.key;
  const summary = item.json.fields?.summary;
  const status = item.json.fields?.status?.name || 'Unknown';
  const link = `https://joacademydev.atlassian.net/browse/${key}`;
  const statusLower = status.toLowerCase();

  // Skip Ready for QA and Canceled entirely
  if (excludedStatuses.includes(statusLower)) continue;

  const acted = iActedOnDate(item);
  const reported = iReportedIt(item);

  // Tested section — if you acted on it today
  if (acted) {
    if (!seenTested.has(key)) {
      seenTested.add(key);
      tested.push({ key, summary, status, link });
    }
  }

// Bugs section — if you reported it AND created it on report date
const createdDate = item.json.fields?.created?.slice(0, 10);
const openedToday = createdDate === reportDate;

if (reported && openedToday && !canceledStatuses.includes(statusLower)) {
    if (!seenBugs.has(key)) {
      seenBugs.add(key);
      bugs.push({ key, summary, status, link });
    }
  }
}

return [{ json: { tested, bugs } }];

const myAccountId = '712020:73241cb0-4434-4afb-a9c9-1a320a644c30';
const reportDate = $('Calculate Report Date').first().json.reportDate;

const filtered = $input.all().filter(item => {
  const comments = item.json.fields?.comment?.comments || [];
  return comments.some(c =>
    c.author?.accountId === myAccountId &&
    c.created?.slice(0, 10) === reportDate
  );
});

for (const item of filtered) {
  item.json._otherTicket = true;
}

return filtered;

const requestedDate = $input.first().json.query?.date;

function isValidDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value;
}

function addDays(dateString, days) {
  const date = new Date(`${dateString}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

let reportDate;
let triggerSource;

if (requestedDate !== undefined) {
  if (typeof requestedDate !== 'string' || !isValidDate(requestedDate)) {
    throw new Error('The date query parameter must be a real calendar date in YYYY-MM-DD format, for example ?date=2026-07-21');
  }
  reportDate = requestedDate;
  triggerSource = 'webhook';
} else {
  // The Docker configuration sets Asia/Amman as the n8n timezone.
  const now = new Date();
  const daysBack = now.getDay() === 6 ? 3 : 1; // Saturday reports Wednesday; all other days report yesterday.
  reportDate = addDays(now.toLocaleDateString('en-CA', { timeZone: 'Asia/Amman' }), -daysBack);
  triggerSource = 'schedule';
}

return [{ json: { reportDate, reportDateEnd: addDays(reportDate, 1), triggerSource } }];

const seen = new Set();
const unique = [];

for (const item of $input.all()) {
  const key = item.json.key;
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(item);
  }
}

return unique;
